      "A Lei nº 4.570, de 14 de junho de 1984, é a Lei de Organização Básica da PMMA — trata da estrutura organizacional da corporação (comandos, unidades, subunidades), sendo frequentemente alterada por leis posteriores que criam ou reestruturam batalhões e comandos regionais, conforme a necessidade operacional do Estado.",
      "Ambas as leis são emendadas com bastante frequência — só nos últimos anos foram identificadas alterações por leis como a 7.855/2003, 8.080/2004, 8.362/2005, 8.449/2006, 8.519/2006, 8.591/2007 (mudança de regime remuneratório), 10.131/2014, 11.528/2021, 11.813/2022, e 12.597/2025, além de projeto de lei específico sobre promoções em tramitação em 2024. Isso reforça a importância de sempre estudar pelo texto consolidado mais atualizado disponível, nunca por uma versão antiga isolada."
