    "corpo": [
      "O Estatuto da PMMA define comando como a soma de autoridade, deveres e responsabilidades de que o militar é investido legalmente, quando conduz homens ou dirige uma Organização Policial-Militar — o comando está vinculado ao grau hierárquico e constitui prerrogativa impessoal, ou seja, pertence à função/posto, não à pessoa que a exerce em determinado momento.",
      "O oficial é preparado ao longo da carreira para o exercício do comando, da chefia e da direção das Organizações Policiais-Militares — refletindo que a progressão na carreira de oficial está diretamente ligada ao desenvolvimento da capacidade de comandar, não apenas ao acúmulo de tempo de serviço.",
      "Um ponto expressamente destacado no próprio Estatuto, e que se conecta diretamente ao já estudado no módulo de Ética: a subordinação não afeta, de modo algum, a dignidade pessoal do militar, e decorre exclusivamente da estrutura hierárquica da Polícia Militar — reforçando legalmente que a relação hierárquica nunca legitima tratamento indigno ou humilhante ao subordinado, mesmo dentro da cadeia de comando."
    ],
    "pontosChave": [
      "Comando é prerrogativa impessoal, vinculada ao grau hierárquico — pertence à posição, não à pessoa isoladamente.",
      "Oficial é formado ao longo da carreira para exercer comando, chefia e direção de organizações policiais-militares.",
      "Estatuto afirma expressamente: subordinação não afeta a dignidade pessoal do militar — reforça o já estudado em Ética."
    ],
