        "texto": "O caráter impessoal do comando significa que ele existe independentemente de quem o exerce em determinado momento — quando um oficial é substituído, o comando permanece, atribuído a quem quer que ocupe aquela posição, o que reforça a continuidade institucional acima de qualquer pessoa específica."
