    "corpo": [
      "Agregação é a situação em que o militar deixa temporariamente de ocupar vaga na escala hierárquica do seu quadro, sem contudo deixar de pertencer aos quadros da corporação — ocorre em hipóteses específicas (afastamento para exercer função em outro órgão, licença de longa duração, entre outras previstas em lei). Enquanto agregado, o militar não pode ocupar vaga na escala hierárquica nem ser promovido, conforme já reconhecido em jurisprudência sobre o tema.",
      "A competência para a agregação de policiais militares é indelegável do Governador do Estado — ponto de atenção específico já cobrado em prova, reforçando que se trata de ato de competência exclusiva do Chefe do Poder Executivo estadual, não passível de delegação a outra autoridade, mesmo dentro da própria corporação.",
      "O Estatuto também disciplina o exercício de cargos e funções em órgãos externos à corporação (assessoria militar do Governador, gabinetes de outros Poderes, Secretaria de Segurança Pública, entre outros listados especificamente em lei) — os policiais militares da ativa só podem ser nomeados ou designados para tais cargos observadas as vagas previstas para o pessoal PM nos respectivos quadros, refletindo um controle rigoroso sobre o afastamento de militares para funções fora da estrutura própria da corporação."
    ],
