        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Deveres, restrições e situações funcionais\", a ideia principal é: Agregação é a situação em que o militar deixa temporariamente de ocupar vaga na escala hierárquica do seu quadro, sem contudo deixar de pertencer aos quadros da corporação — ocorre em hipóteses específicas (afastamento para exercer função em outro órgão, licença de longa duração, entre outras previstas em lei). Para estudar sem travar, guarde primeiro estas palavras-chave: agregação, cargos e funções externas, competência indelegável. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Agregação é sempre decisão indelegável do Governador — militar agregado não ocupa vaga na escala nem pode ser promovido enquanto durar a situação.",
