    "corpo": [
      "Uma peculiaridade importante e pouco intuitiva da PMMA: a corporação não dispõe de Regulamento Disciplinar próprio — situação também vivenciada por outras instituições militares estaduais brasileiras. O próprio Estatuto (art. 166, Lei 6.513/95) prevê a solução para essa lacuna: são adotados na Polícia Militar do Maranhão, em matéria não regulada na legislação estadual, as leis e regulamentos em vigor no Exército Brasileiro, no que lhes for pertinente.",
      "Na prática, isso significa que o Regulamento Disciplinar do Exército (RDE) é aplicado subsidiariamente à PMMA para reger as transgressões disciplinares e as punições correspondentes — essa aplicação subsidiária tem base legal expressa desde a redação original do art. 18 do Decreto-Lei 667/69 (que reorganiza as polícias militares e corpos de bombeiros militares dos Estados), que previa que as polícias militares seriam regidas por regulamento disciplinar à semelhança do RDE, adaptado às condições especiais de cada corporação.",
      "O art. 59 do Estatuto da PMMA prevê expressamente que 'o Regulamento Disciplinar da Polícia Militar especificará as transgressões disciplinares' e as normas de aplicação de penas — mas, na ausência desse regulamento próprio efetivamente editado, a corporação segue aplicando o RDE por força da regra de aplicação subsidiária já mencionada. Esse é um ponto de acentuada peculiaridade institucional, que já gerou inclusive debate acadêmico e prático sobre os limites dessa aplicação, especialmente após mudanças na legislação federal (assunto do próximo capítulo)."
    ],
