      "O próprio Estatuto da PMMA (art. 58) estabelece que, enquanto o Estado do Maranhão não dispuser de Tribunal Militar próprio, a Auditoria da Justiça Militar Estadual é o órgão competente para processar e julgar os militares estaduais nos crimes definidos em lei como militares — cabendo ao Tribunal de Justiça do Estado funcionar como instância recursal (segunda instância), conforme a Organização Judiciária Militar e a Lei de Organização Judiciária do Estado.",
      "Essa estrutura é a aplicação prática, no Maranhão, do modelo já estudado no módulo de Direito Processual Penal Militar: em estados que não possuem Tribunal de Justiça Militar como órgão específico de segunda instância, o próprio Tribunal de Justiça (por meio de câmara ou seção especializada) exerce essa função — o Maranhão se enquadra nessa situação, sem Tribunal Militar próprio, dependendo do Tribunal de Justiça estadual para os recursos.",
      "A Auditoria da Justiça Militar Estadual funciona como órgão de primeira instância, correspondente, em sua lógica, ao Conselho de Justiça já estudado no módulo de Processual Penal Militar (composto por juiz togado e oficiais) — a estrutura específica de composição e funcionamento dessa Auditoria no Maranhão segue a Organização Judiciária Militar aplicável, sendo recomendável a verificação da legislação estadual mais atualizada sobre o tema antes de aprofundar detalhes muito específicos de composição."
